def summarize_ranges(nums: list[int]) -> str:
    sorted_nums = sorted(set(nums))
    result = []
    i = 0
    n = len(sorted_nums)

    while i < n:
        start = sorted_nums[i]
        j = i + 1

        while j < n and sorted_nums[j] == sorted_nums[j - 1] + 1:
            j += 1

        end = sorted_nums[j - 1]
        length = j - i

        if length >= 3:
            result.append(f"{start}..{end}")
        else:
            for k in range(i, j):
                result.append(str(sorted_nums[k]))

        i = j

    return ",".join(result)
